        private void BeginHeroTransition(HeroKind kind){if(heroTransitionRunning)return;StartCoroutine(HeroTransitionRoutine(kind));}
        private IEnumerator HeroTransitionRoutine(HeroKind kind)
        {
            heroTransitionRunning=true;yield return new WaitForEndOfFrame();Texture2D capture=ScreenCapture.CaptureScreenshotAsTexture();if(capture==null){SetHero(kind);StartRun();heroTransitionRunning=false;yield break;}
            var overlay=Rect("HeroShatterTransition",modernCanvas.transform);Stretch(overlay,0,0,0,0);overlay.SetAsLastSibling();float width=overlay.rect.width,height=overlay.rect.height;Vector2 origin=new Vector2(((int)kind-1)*width*.285f,-height*.015f);var random=new System.Random(1709+(int)kind*811);Color crackColor=kind==HeroKind.Amelia?new Color(1f,.72f,.18f):kind==HeroKind.Sam?new Color(.92f,.08f,.18f):new Color(.10f,.80f,1f);
            const int edgeCount=24;var edge=new Vector2[edgeCount];int cursor=0;for(int i=0;i<=6;i++)edge[cursor++]=new Vector2(-width*.5f+width*i/6f,height*.5f);for(int i=1;i<=6;i++)edge[cursor++]=new Vector2(width*.5f,height*.5f-height*i/6f);for(int i=1;i<=6;i++)edge[cursor++]=new Vector2(width*.5f-width*i/6f,-height*.5f);for(int i=1;i<6;i++)edge[cursor++]=new Vector2(-width*.5f,-height*.5f+height*i/6f);
            var rings=new Vector2[3,edgeCount];for(int i=0;i<edgeCount;i++){Vector2 ray=edge[i]-origin;float near=.16f+(float)random.NextDouble()*.07f,middle=.43f+(float)random.NextDouble()*.12f;rings[0,i]=origin+ray*near;rings[1,i]=origin+ray*middle;rings[2,i]=edge[i];}
            var shards=new List<UiPolygonShard>(edgeCount*5);var velocities=new List<Vector2>(edgeCount*5);var spins=new List<Vector3>(edgeCount*5);var delays=new List<float>(edgeCount*5);
            Action<Vector2,Vector2,Vector2> addShard=(a,b,c)=>{Vector2 center=(a+b+c)/3f,min=Vector2.Min(a,Vector2.Min(b,c)),max=Vector2.Max(a,Vector2.Max(b,c));var rt=Rect("GlassShard",overlay);rt.anchorMin=rt.anchorMax=new Vector2(.5f,.5f);rt.pivot=Vector2.one*.5f;rt.anchoredPosition=center;rt.sizeDelta=max-min+Vector2.one*3;var shard=rt.gameObject.AddComponent<UiPolygonShard>();shard.source=capture;shard.points=new[]{a-center,b-center,c-center};shard.uvs=new[]{ScreenUv(a,width,height),ScreenUv(b,width,height),ScreenUv(c,width,height)};shard.color=Color.white;shards.Add(shard);Vector2 away=(center-origin).normalized;float distance=Vector2.Distance(center,origin)/Mathf.Max(width,height);velocities.Add(away*(250+(float)random.NextDouble()*430)+new Vector2(((float)random.NextDouble()-.5f)*90,40+(float)random.NextDouble()*130));spins.Add(new Vector3(((float)random.NextDouble()-.5f)*210,((float)random.NextDouble()-.5f)*210,((float)random.NextDouble()-.5f)*330));delays.Add(distance*.20f+(float)random.NextDouble()*.045f);};
            for(int i=0;i<edgeCount;i++){int next=(i+1)%edgeCount;addShard(origin,rings[0,i],rings[0,next]);for(int ring=0;ring<2;ring++){Vector2 a=rings[ring,i],b=rings[ring,next],c=rings[ring+1,next],d=rings[ring+1,i];if(random.NextDouble()>.5){addShard(a,b,c);addShard(a,c,d);}else{addShard(a,b,d);addShard(b,c,d);}}}
            var flash=Rect("CrackFlash",overlay);Stretch(flash,0,0,0,0);var flashImage=flash.gameObject.AddComponent<Image>();flashImage.raycastTarget=false;var cracks=new List<Image>(36);for(int i=0;i<9;i++){int ray=(i*edgeCount/9+(int)kind*2)%edgeCount;Vector2 a=origin,b=rings[0,ray],c=rings[1,ray];AddCrackSegment(overlay,a,b,crackColor,3.2f,cracks);AddCrackSegment(overlay,b,c,crackColor,2.1f,cracks);Vector2 branch=b+(rings[0,(ray+1)%edgeCount]-b)*(.28f+(float)random.NextDouble()*.22f);AddCrackSegment(overlay,b,branch,new Color(crackColor.r,crackColor.g,crackColor.b,.78f),1.35f,cracks);}
            float crackTime=0;while(crackTime<.30f){crackTime+=Time.unscaledDeltaTime;float t=Mathf.Clamp01(crackTime/.30f),pulse=Mathf.Sin(t*Mathf.PI);flashImage.color=new Color(crackColor.r,crackColor.g,crackColor.b,pulse*.13f);for(int i=0;i<cracks.Count;i++)cracks[i].color=new Color(cracks[i].color.r,cracks[i].color.g,cracks[i].color.b,Mathf.SmoothStep(0,1,t));yield return null;}
            SetHero(kind);StartRun();Destroy(flash.gameObject);for(int i=0;i<cracks.Count;i++)Destroy(cracks[i].gameObject);
            float elapsed=0,duration=1.12f;while(elapsed<duration){float dt=Time.unscaledDeltaTime;elapsed+=dt;for(int i=0;i<shards.Count;i++){float local=elapsed-delays[i];if(local<=0)continue;var rt=(RectTransform)shards[i].transform;Vector2 velocity=velocities[i];velocity.y-=760*dt;velocities[i]=velocity;rt.anchoredPosition+=velocity*dt;Vector3 spin=spins[i];rt.Rotate(spin.x*dt,spin.y*dt,spin.z*dt,Space.Self);float normalized=Mathf.Clamp01(local/(duration-delays[i])),alpha=1-Mathf.InverseLerp(.55f,1,normalized);rt.localScale=Vector3.one*Mathf.Lerp(1,.82f,normalized);shards[i].color=new Color(1,1,1,alpha);}yield return null;}
            Destroy(overlay.gameObject);Destroy(capture);heroTransitionRunning=false;
        }
        private static Vector2 ScreenUv(Vector2 point,float width,float height)=>new Vector2(point.x/width+.5f,point.y/height+.5f);
        private static void AddCrackSegment(Transform parent,Vector2 from,Vector2 to,Color color,float thickness,List<Image> result){Vector2 delta=to-from;var line=new GameObject("Fracture",typeof(RectTransform),typeof(Image));var rt=line.GetComponent<RectTransform>();rt.SetParent(parent,false);rt.anchorMin=rt.anchorMax=new Vector2(.5f,.5f);rt.pivot=new Vector2(0,.5f);rt.anchoredPosition=from;rt.sizeDelta=new Vector2(delta.magnitude,thickness);rt.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(delta.y,delta.x)*Mathf.Rad2Deg);var image=line.GetComponent<Image>();image.color=new Color(color.r,color.g,color.b,0);image.raycastTarget=false;result.Add(image);}

