        private void SyncModernUi(bool force=false)
        {
            if(modernCanvas==null||safeAreaRoot==null||menuScreen==null||heroScreen==null||hudScreen==null||heroNameText==null){if(!Application.isPlaying)return;var stale=GameObject.Find("NightfallCanvas");if(stale!=null)Destroy(stale);BuildModernUi();return;}if(hero==null){if(player==null||spriteFactory==null||characterVisual==null)return;SetHero(HeroKind.Amelia);}Rect safe=Screen.safeArea;safeAreaRoot.anchorMin=new Vector2(safe.xMin/Screen.width,safe.yMin/Screen.height);safeAreaRoot.anchorMax=new Vector2(safe.xMax/Screen.width,safe.yMax/Screen.height);
            if(force||uiRenderedState!=state){uiRenderedState=state;menuScreen.SetActive(state==State.Menu);heroScreen.SetActive(state==State.HeroSelect);hudScreen.SetActive(state==State.Playing);upgradeScreen.SetActive(state==State.Upgrade);petScreen.SetActive(state==State.PetUnlock);pauseScreen.SetActive(state==State.Paused);endScreen.SetActive(state==State.Dead||state==State.Victory);if(state==State.Upgrade)RenderUpgradeCards();if(state==State.PetUnlock)RenderPetModal();if(state==State.Dead||state==State.Victory){endTitleText.text=GameLocalization.Tr(state==State.Victory?"ПОБЕДА":"ОПЕРАТИВНИК ПОГИБ");endStatsText.text=LocalizedCount("Уничтожено целей: ","Targets eliminated: ","消灭目标：",kills);}}
            if(state!=State.Playing)return;heroNameText.text=GameLocalization.Tr(hero.displayName);levelText.text=LocalizedCount("УРОВЕНЬ ","LEVEL ","等级 ",level);hpText.text="HP  "+Mathf.CeilToInt(hp)+" / "+Mathf.CeilToInt(maxHp);hpFill.fillAmount=maxHp>0?hp/maxHp:0;xpText.text=(GameLocalization.Current==GameLanguage.Russian?"ОПЫТ":GameLocalization.Current==GameLanguage.English?"XP":"经验")+"  "+xp+" / "+xpNeed;xpFill.fillAmount=xpNeed>0?(float)xp/xpNeed:0;timerText.text=$"{(int)(runTime/60):00}:{(int)(runTime%60):00}";killsText.text=LocalizedCount("УНИЧТОЖЕНО: ","ELIMINATED: ","消灭：",kills);
