        private void ReturnToMainMenu(){foreach(var enemy in enemies){enemy.active=false;if(enemy.go!=null)enemy.go.SetActive(false);}foreach(var projectile in projectiles){projectile.active=false;if(projectile.go!=null)projectile.go.SetActive(false);}currentBoss=null;if(player!=null)player.SetActive(false);state=State.Menu;SyncModernUi(true);}
        public void DebugPreviewUi(string screen)
        {
            if(hero==null)SetHero(HeroKind.Amelia);
            if(screen=="Menu")state=State.Menu;else if(screen=="HeroSelect")state=State.HeroSelect;else if(screen=="HUD"){if(!player.activeSelf)StartRun();state=State.Playing;}else if(screen=="Upgrade"){RollUpgrades();state=State.Upgrade;}else if(screen=="Pet"){petDefinition=PetCatalog.ForOwner(hero.id);petPortrait=Resources.Load<Texture2D>(petDefinition.portraitResource);state=State.PetUnlock;}else if(screen=="Pause")state=State.Paused;else if(screen=="Boss"){if(!player.activeSelf)StartRun();if(currentBoss==null)SpawnBoss(BossKind.EarthDragon);state=State.Playing;}else if(screen=="End")state=State.Victory;SyncModernUi(true);
        }
        public string RunUiLayoutAudit()
        {
            if(modernCanvas==null)return "Canvas is not initialized";Canvas.ForceUpdateCanvases();int issues=0,labels=0,buttons=0;var safe=safeAreaRoot.rect;
            foreach(var label in modernCanvas.GetComponentsInChildren<TMP_Text>(true)){labels++;if(!label.gameObject.activeInHierarchy)continue;label.ForceMeshUpdate();var rt=label.rectTransform;var bounds=label.textBounds.size;if(bounds.x>rt.rect.width+1||bounds.y>rt.rect.height+1){Debug.LogWarning("UI_AUDIT text outside slot: "+HierarchyPath(rt)+$" text={bounds.x:0}x{bounds.y:0} slot={rt.rect.width:0}x{rt.rect.height:0}");issues++;}if(!label.enableWordWrapping&&label.textInfo.lineCount>1){Debug.LogWarning("UI_AUDIT unexpected wrap: "+HierarchyPath(rt));issues++;}}
            foreach(var button in modernCanvas.GetComponentsInChildren<Button>(true)){buttons++;if(button.targetGraphic==null){Debug.LogWarning("UI_AUDIT button has no visual: "+HierarchyPath(button.transform));issues++;}}
            string result=$"UI AUDIT: {issues} issue(s), {labels} TMP labels, {buttons} buttons, SafeArea {safe.width:0}x{safe.height:0}";Debug.Log(result);return result;
        }
        public string RunUiLongStringAudit(){if(modernCanvas==null)return "Canvas is not initialized";var labels=modernCanvas.GetComponentsInChildren<TMP_Text>(true);var original=new string[labels.Length];for(int i=0;i<labels.Length;i++){original[i]=labels[i].text;if(labels[i].transform.parent!=null&&labels[i].transform.parent.name.Contains("NameSlot"))labels[i].text="ОЧЕНЬ ДЛИННОЕ ИМЯ ОПЕРАТИВНИКА БЮРО";else if(labels[i].transform.parent!=null&&labels[i].transform.parent.name.Contains("DescriptionSlot"))labels[i].text="Длинное тестовое описание способности проверяет перенос строк, границы фиксированного контейнера и то, что соседние элементы интерфейса никогда не сдвигаются из-за объёма текста.";}string result=RunUiLayoutAudit();for(int i=0;i<labels.Length;i++)labels[i].text=original[i];Canvas.ForceUpdateCanvases();Debug.Log("UI LONG STRING "+result);return result;}
