        private static void Stretch(RectTransform rt,float left,float right,float top,float bottom){rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=new Vector2(left,bottom);rt.offsetMax=new Vector2(-right,-top);}
        private static void Anchor(RectTransform rt,Vector2 min,Vector2 max,Vector2 position){rt.anchorMin=min;rt.anchorMax=max;rt.pivot=(min+max)*.5f;rt.anchoredPosition=position;}
        private static void SetAnchored(RectTransform rt,Vector2 min,Vector2 max,Vector2 position,Vector2 size){rt.anchorMin=min;rt.anchorMax=max;rt.pivot=(min+max)*.5f;rt.anchoredPosition=position;rt.sizeDelta=size;}
        private static void Clear(Transform root){for(int i=root.childCount-1;i>=0;i--)Destroy(root.GetChild(i).gameObject);}
        private Sprite TextureSprite(Texture2D texture){if(texture==null)return null;return Sprite.Create(texture,new Rect(0,0,texture.width,texture.height),new Vector2(.5f,.5f),100);}
        private static Sprite CreateNineSlice(string name,Color center,Color edge){const int s=24,b=6;var texture=new Texture2D(s,s,TextureFormat.RGBA32,false){name=name,filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};var pixels=new Color[s*s];for(int y=0;y<s;y++)for(int x=0;x<s;x++){bool border=x<b||x>=s-b||y<b||y>=s-b;pixels[y*s+x]=border?edge:center;}texture.SetPixels(pixels);texture.Apply(false,true);return Sprite.Create(texture,new Rect(0,0,s,s),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(b,b,b,b));}
        private static Sprite CreateHorizontalGradient(string name,Color left,Color middle,Color right){const int width=128,height=8;var texture=new Texture2D(width,height,TextureFormat.RGBA32,false){name=name,filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};var pixels=new Color[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){float t=x/(float)(width-1);Color baseColor=t<.72f?Color.Lerp(left,middle,t/.72f):Color.Lerp(middle,right,(t-.72f)/.28f);float highlight=1f+Mathf.Sin(y/(float)(height-1)*Mathf.PI)*.14f;pixels[y*width+x]=new Color(Mathf.Clamp01(baseColor.r*highlight),Mathf.Clamp01(baseColor.g*highlight),Mathf.Clamp01(baseColor.b*highlight),1);}texture.SetPixels(pixels);texture.Apply(false,true);return Sprite.Create(texture,new Rect(0,0,width,height),new Vector2(.5f,.5f),100);}
    }

    public sealed class SafeAreaLayout:MonoBehaviour
    {
        private Rect lastSafe;private Vector2Int lastScreen;
        private void Update(){if(lastSafe==Screen.safeArea&&lastScreen.x==Screen.width&&lastScreen.y==Screen.height)return;lastSafe=Screen.safeArea;lastScreen=new Vector2Int(Screen.width,Screen.height);var rt=(RectTransform)transform;rt.anchorMin=new Vector2(lastSafe.xMin/Screen.width,lastSafe.yMin/Screen.height);rt.anchorMax=new Vector2(lastSafe.xMax/Screen.width,lastSafe.yMax/Screen.height);rt.offsetMin=rt.offsetMax=Vector2.zero;}
    }

    [ExecuteAlways]
    public sealed class UiLayoutBounds:MonoBehaviour
    {
        public enum Kind{Text,Description,Button}
        public Kind kind;public bool visible;private Image overlay;
        private void Update(){if(overlay==null){overlay=GetComponent<Image>();if(overlay==null)overlay=gameObject.AddComponent<Image>();overlay.raycastTarget=false;}overlay.enabled=visible;overlay.color=kind==Kind.Button?new Color(1,.72f,.12f,.10f):kind==Kind.Description?new Color(.25f,1,.35f,.10f):new Color(.12f,.78f,1,.10f);}
    }

    public sealed class UiScreenShard:MaskableGraphic
    {
        public Texture source;public Rect uvRect;public bool flip;public override Texture mainTexture=>source!=null?source:Texture2D.whiteTexture;
        protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();Rect r=rectTransform.rect;Vector2 bl=new Vector2(r.xMin,r.yMin),br=new Vector2(r.xMax,r.yMin),tl=new Vector2(r.xMin,r.yMax),tr=new Vector2(r.xMax,r.yMax);Vector2 uvBl=new Vector2(uvRect.xMin,uvRect.yMin),uvBr=new Vector2(uvRect.xMax,uvRect.yMin),uvTl=new Vector2(uvRect.xMin,uvRect.yMax),uvTr=new Vector2(uvRect.xMax,uvRect.yMax);Color32 c=color;if(!flip){vh.AddVert(bl,c,uvBl);vh.AddVert(br,c,uvBr);vh.AddVert(tl,c,uvTl);}else{vh.AddVert(tr,c,uvTr);vh.AddVert(tl,c,uvTl);vh.AddVert(br,c,uvBr);}vh.AddTriangle(0,1,2);}
    }

    public sealed class UiPolygonShard:MaskableGraphic
    {
        public Texture source;public Vector2[] points,uvs;public override Texture mainTexture=>source!=null?source:Texture2D.whiteTexture;
        protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();if(points==null||uvs==null||points.Length<3||uvs.Length<3)return;Color32 c=color;for(int i=0;i<3;i++)vh.AddVert(points[i],c,uvs[i]);vh.AddTriangle(0,1,2);}
    }
}
